import{_ as i,P as o,d as r,e as l,y as t,q as n}from"./chunks/framework.D7CAgLCq.js";const s="/xi-kari-skill/handbook/images/joint-feasibility.svg",m=JSON.parse('{"title":"每件事都做得到，为什么放在一起就做不到","description":"方案共享时段和容量，单独可做不等于能够共同完成。","frontmatter":{"title":"每件事都做得到，为什么放在一起就做不到","description":"方案共享时段和容量，单独可做不等于能够共同完成。"},"headers":[],"relativePath":"concepts/joint-feasibility.md","filePath":"concepts/joint-feasibility.md"}'),h={name:"concepts/joint-feasibility.md"};function d(c,a,p,_,b,f){const e=o("JointExplorer");return r(),l("div",null,[a[0]||(a[0]=t('<h1 id="每件事都做得到-为什么放在一起就做不到" tabindex="-1">每件事都做得到，为什么放在一起就做不到 <a class="header-anchor" href="#每件事都做得到-为什么放在一起就做不到" aria-label="Permalink to &quot;每件事都做得到，为什么放在一起就做不到&quot;">​</a></h1><p>两项任务各自可行，排成同一份计划会发生什么？</p><p><strong>方案共享时段和容量，单独可做不等于能够共同完成。</strong></p><h2 id="从具体情景看区别" tabindex="-1">从具体情景看区别 <a class="header-anchor" href="#从具体情景看区别" aria-label="Permalink to &quot;从具体情景看区别&quot;">​</a></h2><p>原文给出两项单位任务：每项都要占用一个完整时段，而且都必须在第一期结束前完成；第一期的容量却只有1。拿出任何一项单独看，资源都足够，两项同时进入计划，就没有满足原截止时间的排程。将同期容量增加到2可以改变结果；若允许把一项截止时间合法改到第二期，并且第二期有容量1，也可以得到另一种可行安排。</p><p>但保留原来的两个截止时间、只在第二期增加容量，并不能补回已经错过的第一期。这一例子帮助读者把“总资源看起来够”和“资源在要求的位置、时间可用”区分开。它也提醒我们，改变期限是改变条件，不能在事后悄悄换成新的成功标准。</p><figure class="concept-figure"><img src="'+s+'" alt="两项任务争用同一期容量"><figcaption>增加未来容量与合法改变任务期限，是两种不同操作。</figcaption></figure><h2 id="改变条件-看看有什么不同" tabindex="-1">改变条件，看看有什么不同 <a class="header-anchor" href="#改变条件-看看有什么不同" aria-label="Permalink to &quot;改变条件，看看有什么不同&quot;">​</a></h2>',8)),n(e),a[1]||(a[1]=t('<h2 id="总时数之外-还要看可用整段" tabindex="-1">总时数之外，还要看可用整段 <a class="header-anchor" href="#总时数之外-还要看可用整段" aria-label="Permalink to &quot;总时数之外，还要看可用整段&quot;">​</a></h2><p>原文<a href="./../theory/part-07.html#section-7-3-9">§7.3.9</a>补充了一个可行性条件：若任务需要连续时段，总空闲时间相同的人仍可能有不同机会。默认联系人、待命和临时补缺责任，会把可用时间切碎；即使实际呼叫很少，也可能无法安排一段可预期的学习或休息。</p><p>教学情景：一项练习必须连续两小时完成。一人有固定的两小时，另一人总计也有两小时却只有不可预知的短间隙。总量相同不使方案同样可行。分别记录整段长度和可预期性，不把连续性再折成时数与已经记录的工时相加。</p><h2 id="另一个问题-信息不全时-有没有对各种可能都合格的动作" tabindex="-1">另一个问题：信息不全时，有没有对各种可能都合格的动作 <a class="header-anchor" href="#另一个问题-信息不全时-有没有对各种可能都合格的动作" aria-label="Permalink to &quot;另一个问题：信息不全时，有没有对各种可能都合格的动作&quot;">​</a></h2><p><a href="/xi-kari-skill/handbook/theory/appendix-c.html#section-c-12">附录C.12</a>的共同可行动作命题讲的是相关但不同的问题。设观察之后还剩两个可能的状态：一个状态下合格的动作只有{左}，另一个只有{右}。两个状态各自都有办法，合格集合的交集却是空的，仅凭这次观察选出的任何一个动作，都不能对两个状态都合格。</p><p>如果两个状态都允许一个已经获得授权的保全动作，交集就可以非空，而状态仍然没有被完全识别。追加观察也可能有帮助，但它的代价、及时性、风险和能否取得都要另行评估；继续调查不会自动免费，也不一定有用。</p><div class="xk-table"><table><thead><tr><th>主张</th><th>须核对</th></tr></thead><tbody><tr><td>每项任务单独可做</td><td>各项任务自身的约束</td></tr><tr><td>全部任务可以一起做</td><td>联合起来的资源与截止约束</td></tr><tr><td>信息不全时仍有一个动作可行</td><td>所列各个相容状态有没有共同的合格动作</td></tr></tbody></table></div><p>命题里的合格集合，必须已经把任务所要求的资源、保护和有效权限算进去；在数学上写出一个动作，不能代替这些现实条件。</p><h2 id="回到原文" tabindex="-1">回到原文 <a class="header-anchor" href="#回到原文" aria-label="Permalink to &quot;回到原文&quot;">​</a></h2><blockquote><p>每项单独可做，联合起来却没有可行的排程。</p></blockquote><ul><li><a href="/xi-kari-skill/handbook/theory/appendix-c.html#section-c-12">附录C.12 局部成功的三种组合边界</a></li></ul><h2 id="这处区别能说明到哪里" tabindex="-1">这处区别能说明到哪里 <a class="header-anchor" href="#这处区别能说明到哪里" aria-label="Permalink to &quot;这处区别能说明到哪里&quot;">​</a></h2><p>这是由给定约束成立的原文教学例，不认证现实需求或容量。现实中的加资源、改截止时间和执行安排，还须有相应事实依据与权限。</p><h2 id="接着理解" tabindex="-1">接着理解 <a class="header-anchor" href="#接着理解" aria-label="Permalink to &quot;接着理解&quot;">​</a></h2><ul><li><a href="./responsibility.html">实际做事的人，为什么不等于全部责任人</a></li><li><a href="./chain.html">两段都有效，整条链为什么仍可能无效</a></li></ul>',15))])}const k=i(h,[["render",d]]);export{m as __pageData,k as default};
